size_t nbits = binfo->nbits;
size_t nbits_per_word = binfo->nbits_per_word;
size_t shift = binfo->shift;
bitmap_t full_mask = binfo->mask;

size_t nwords = (nbits + nbits_per_word - 1) >> shift;
for (size_t wi = 0; wi < nwords; ++wi) {
    // Determine mask for the current word (handles a partially‑filled final word).
    bitmap_t word_mask = full_mask;
    if (wi == nwords - 1) {
        size_t remaining = nbits & (nbits_per_word - 1);
        if (remaining != 0) {
            word_mask = (static_cast<bitmap_t>(1) << remaining) - 1;
        }
    }

    std::atomic<bitmap_t>* aword =
        reinterpret_cast<std::atomic<bitmap_t>*>(bitmap + wi);

    bitmap_t cur = aword->load(std::memory_order_relaxed);
    while (true) {
        // Bits that are still zero in this word.
        bitmap_t zero = (~cur) & word_mask;
        if (zero == 0) {
            break; // all bits set, move to next word.
        }

        // Isolate the least‑significant zero bit.
        bitmap_t bit = zero & static_cast<bitmap_t>(-static_cast<std::make_signed_t<bitmap_t>>(zero));

        // Try to set it atomically.
        bitmap_t expected = cur;
        bitmap_t desired = cur | bit;
        if (aword->compare_exchange_weak(
                expected, desired,
                std::memory_order_acq_rel,
                std::memory_order_relaxed)) {
            // Success – compute and return the global bit index.
            size_t bit_index = (wi << shift) + std::countr_zero(bit);
            return bit_index;
        }

        // CAS failed – another thread modified the word; retry with the new value.
        cur = expected;
    }
}
return nbits;

